# Load all the grids from the session
import os
import re
import json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')

# Extract demo pairs
G = {}
for line in t.split('\n'):
    if line.startswith('Demo pair') or line.startswith('Test input'):
        pass
    elif not line.strip():
        pass

# Let's parse more properly
demo_pattern = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):')
current_key = None
current_rows = []
rows_so_far = []

for match in demo_pattern.finditer(t):
    header_type, task_name, h, w = match.groups()
    if task_name not in G:
        if header_type == 'Test input' or current_key is None:
            current_key = task_name
            current_rows = []

        # Parse the grid that follows
        pos = match.end()
        grid_text = t[pos:pos+h*w]
        rows_str = grid_text.split('\n')[:h]

        if current_key and (header_type == 'Test input' or not G.get(current_key)):
            grid = [[int(c) for c in row[:w]] for row in rows_str]
            if current_key:
                key_label = 'Test input' if header_type == 'Test input' else f'Demo pair ~task~-input'
                # Check if this is output
                if header_type == 'output':
                    G[f"{task_name}-output"] = grid
                elif header_type == 'input':
                    G[f"{task_name}-input"] = grid
                elif header_type == 'Test input':
                    G[f"{task_name}-test"] = grid

print(f"Keys found: {list(G.keys())[:20]}")

